    "Nếu đã thanh toán mà chưa nghe được, hãy nhờ nhân viên kiểm tra trước khi thanh toán lại. Dùng cùng trình duyệt và giữ dữ liệu của trang để tiếp tục dùng vé.": "Pokud jste zaplatili, ale nedostali jste zpětnou vazbu, požádejte zaměstnance o kontrolu před dalším zaplacením. Chcete-li nadále používat vstupenky, použijte stejný prohlížeč a ponechte si data webu.",
    "Nội dung đang được cập nhật theo ngôn ngữ bạn chọn.": "Obsah se aktualizuje ve vámi zvoleném jazyce.",
