    "Quan sát sắc lông, dáng đi và những chuyển động nhỏ. Giữ khoảng cách, dành sự yên tĩnh cho các loài vật và để sự tò mò dẫn lối.": "Pozorujte barvu srsti, chůzi a drobné pohyby. Udržujte si odstup, nechte zvířata na pokoji a nechte se vést svou zvědavostí.",
    "Quyền nghe thuyết minh": "Právo poslouchat vysvětlení",
    "Quyền nghe đã hết hạn. Nếu vé của bạn vẫn còn hạn nhưng không mở được, hãy nhờ nhân viên kiểm tra.": "Platnost oprávnění k poslechu vypršela. Pokud je vaše jízdenka stále platná, ale nelze ji otevřít, požádejte zaměstnance o kontrolu.",
