    "Vé này đã được kích hoạt. Nếu chưa nhận được vé, hãy nhờ nhân viên hỗ trợ; không cần trả tiền lại.": "Dieses Ticket wurde aktiviert. Wenn Sie Ihr Ticket nicht erhalten haben, wenden Sie sich bitte an das Personal. keine Notwendigkeit, etwas zurückzuzahlen.",
    "Vé này đã được kích hoạt. Nếu không mở được quyền nghe, hãy nhờ nhân viên hỗ trợ; không cần trả tiền lại.": "Dieses Ticket wurde aktiviert. Wenn Sie die Hörrechte nicht öffnen können, wenden Sie sich bitte an den Support. keine Notwendigkeit, etwas zurückzuzahlen.",
    "Vé thuyết minh": "Audioguide-Tickets",
    "Vé đang thuộc một địa chỉ khác": "Das Ticket befindet sich an einer anderen Adresse",
    "Vé đã hết hạn hoặc quyền tham quan không còn hợp lệ. Nếu mất token, vui lòng liên hệ nhân viên; không thanh toán lại chỉ để khôi phục token.": "Das Ticket ist abgelaufen oder der Eintritt ist nicht mehr gültig. Sollten Sie Ihren Token verlieren, wenden Sie sich bitte an das Personal; Zahlen Sie nicht erneut, nur um Token wiederherzustellen.",
    "Vé đã kích hoạt": "Ticket wurde aktiviert",
    "Vé đã sẵn sàng. Mời bạn chọn điểm tham quan và bắt đầu nghe.": "Tickets sind fertig. Bitte wählen Sie Ihr Ziel und beginnen Sie mit dem Zuhören.",
    "Vé đã được kích hoạt. Bạn có thể bắt đầu khám phá và nghe thuyết minh.": "Ticket wurde aktiviert. Sie können mit der Erkundung beginnen und sich die Erzählung anhören.",
    "Vé đã được lưu trên thiết bị.": "Das Ticket wurde auf dem Gerät gespeichert.",
    "Về bản đồ và giọng đọc demo": "Über die Karte und die Demostimme",
    "Vị trí tham khảo & minh họa": "Referenzorte und Abbildungen",
    "Vị trí tham khảo và minh họa, chưa khảo sát thực địa; không xác nhận lối vào hay khả năng tiếp cận. Đường nối các điểm không phải tuyến đi bộ.": "Referenz- und illustrativer Standort, keine Feldbesichtigung; bestätigt weder den Zutritt noch die Zugänglichkeit. Straßenverbindungspunkte sind keine Wanderwege.",
    "Vị trí trình diễn": "Demonstrationsort",
    "Vị trí đang dùng trên bản đồ": "Genutzter Standort auf der Karte",
    "Xem bản đồ khám phá": "Erkundungskarte anzeigen",
    "Xem danh sách điểm tham quan và lộ trình trong mục Khám phá.": "Sehen Sie sich die Liste der Attraktionen und Routen im Abschnitt „Erkunden“ an.",
    "Xem giới thiệu": "Siehe Einleitung",
    "Xem sơ đồ chính thức ↗": "Siehe offizielles Diagramm ↗",
    "Xác minh lại phiên": "Überprüfen Sie die Sitzung erneut",
