    "Đây là quyền nghe trong đồ án demo, không phải vé vào cổng Thảo Cầm Viên.": "Hierbei handelt es sich um ein Hörrecht im Demoprojekt, nicht um eine Eintrittskarte Thảo Cầm Viên.",
    "Đã chọn": "Ausgewählt",
    "Đã chọn {0}/{1} điểm": "Ausgewählte {0}/{1} Punkte",
    "Đã kích hoạt nghe": "Zuhören aktiviert",
    "Đã lưu quyền truy cập. Hãy xác minh lại, không đổi mã hoặc thanh toán lần nữa.": "Zugriff gespeichert. Bitte verifizieren Sie sich erneut, lösen Sie den Code nicht ein und zahlen Sie nicht erneut.",
    "Đã tạo lượt nghe thử. Tiếp tục xác nhận thanh toán mô phỏng bên dưới.": "Testhören erstellt. Bestätigen Sie unten weiterhin die simulierte Zahlung.",
    "Đã xác nhận thanh toán mô phỏng. Bấm kích hoạt vé để bắt đầu nghe.": "Simulierte Zahlung bestätigt. Klicken Sie auf „Ticket aktivieren“, um mit dem Zuhören zu beginnen.",
    "Đã xác nhận thanh toán.": "Zahlung bestätigt.",
    "Đã xóa toàn bộ phiên khách trên trình duyệt này.": "Alle Clientsitzungen in diesem Browser wurden gelöscht.",
    "Đóng": "Schließen",
    "Đóng danh sách": "Schließen Sie die Liste",
    "Đường nối và khoảng cách ước tính; không phải đường đi bộ thực tế.": "Geschätzte Nähte und Entfernungen; Kein echter Wanderweg.",
    "Đến trang Khám phá": "Gehen Sie zur Seite „Erkunden“.",
    "Để bảo vệ vé, hệ thống chưa gửi quyền truy cập sang địa chỉ hiện tại. Hãy mở lại trang đã dùng hoặc nhờ nhân viên kiểm tra.": "Um das Ticket zu schützen, hat das System keine Zugriffsberechtigung an die aktuelle Adresse gesendet. Bitte öffnen Sie die verwendete Seite erneut oder bitten Sie einen Mitarbeiter, dies zu überprüfen.",
    "Để câu chuyện dẫn đường.": "Lassen Sie sich von der Geschichte leiten.",
    "Địa điểm": "Standort",
    "Đọc lời thuyết minh": "Lesen Sie die Erzählung",
    "Động vật": "Tiere",
    "điểm": "Punkte",
    "điểm tham quan": "Sehenswürdigkeiten",
    "điểm ·": "Punkt ·",
    "đóng góp bản đồ": "beigetragene Karte",
    "ước tính từ thiết bị": "vom Gerät geschätzt",
    "Ảnh minh họa loài": "Artenillustration",
    "Ảnh tư liệu địa điểm": "Dokumentationsfoto des Standorts",
    "Ảnh:": "Foto:",
    "Ở bản demo, nút bên dưới giả lập kết quả từ cổng thanh toán. Không có giao dịch tiền thật.": "In der Demo simuliert die Schaltfläche unten Ergebnisse des Zahlungsgateways. Kein Echtgeldhandel.",
    "— âm thanh chưa sẵn sàng": "– Ton nicht bereit",
    "← Trở lại bản đồ": "← Zurück zur Karte",
    "👤 Vị trí hiện tại của bạn": "👤 Ihr aktueller Standort",
    "Cùng khám phá với {0} khách có vé còn hiệu lực": "Entdecken Sie mit {0} Gästen mit gültigen Tickets",
    "Lộ trình demo do nhóm đề xuất — Hươu cao cổ và Voi châu Á": "Vom Team vorgeschlagene Demoroute – Giraffe und Asiatischer Elefant",
    "Tổng khoảng cách đường nối giữa các điểm: khoảng {0} m, không phải đường đi bộ.": "Gesamte Straßenentfernung zwischen den Punkten: ca. {0} m, kein Fußweg.",
    "Tổng khoảng cách đường nối ước tính: {0} m. Không dùng để xác nhận đường đi hoặc khả năng tiếp cận.": "Geschätzte Gesamtstrecke der Rampe: {0} m. Wird nicht zur Bestätigung der Route oder Zugänglichkeit verwendet.",
    "Vị trí mô phỏng theo sơ đồ cho demo; không xác nhận vị trí thực tế của cá thể hoặc cây.": "Simulierter Standort gemäß Diagramm für Demo; bestätigt nicht den tatsächlichen Standort der Person oder des Baumes.",
    "Vị trí tham khảo OSM theo bản ghi nguồn đã lưu; chưa tái xác minh, chưa khảo sát thực địa.": "OSM-Referenzstandort gemäß gespeichertem Quelldatensatz; Noch nicht erneut verifiziert, noch keine Felduntersuchung."
