    "Câu hỏi của bạn": "Tu pregunta",
    "Có. Sau khi kích hoạt, vào Khám phá, chọn điểm tham quan rồi chủ động phát hoặc tạm dừng thuyết minh. Âm thanh không tự phát khi mở trang.": "Sí. Después de la activación, vaya a Explorar, seleccione una atracción y luego reproduzca activamente o ponga en pausa la narración. El sonido no se reproduce automáticamente al abrir la página.",
    "Cùng khám phá với": "Exploremos juntos",
