    "Cần kiểm tra với máy chủ trước khi mở quyền nghe. Bạn không cần nhập mã hoặc thanh toán lại.": "Es necesario consultar con el servidor antes de abrir los permisos de escucha. No es necesario ingresar un código ni pagar nuevamente.",
