    "Dưới tán cây, tìm một chút bình yên.": "Debajo de los árboles, encuentra un poco de paz.",
    "Dấu ấn di sản": "Marca patrimonial",
    "Dừng chân bên những chú chim trĩ. Quan sát sắc lông, lắng nghe âm thanh và khám phá câu chuyện của muôn loài.": "Pase por los faisanes. Observa los colores de las plumas, escucha sonidos y descubre las historias de todas las especies.",
