    "Hỏi đáp tạm thời gián đoạn. Câu hỏi vẫn được giữ để bạn thử lại; bản đồ và thuyết minh vẫn sử dụng được.": "Preguntas y respuestas interrumpidas temporalmente. La pregunta sigue abierta para que vuelvas a intentarlo; Todavía hay mapas y explicaciones disponibles.",
