    "Kích hoạt vé để xem và tùy chỉnh lộ trình.": "Activar billetes para ver y personalizar rutas.",
    "Kết nối bị gián đoạn khi kích hoạt. Nhờ nhân viên kiểm tra kết quả trước khi nhập lại; không cần trả tiền lại.": "Conexión interrumpida durante la activación. Solicite al personal que verifique los resultados antes de volver a ingresar; no es necesario devolver el dinero.",
    "Kết nối bị gián đoạn. Bạn có thể thử lại để tiếp tục lượt đang có.": "Conexión interrumpida. Puedes intentar nuevamente continuar con tu turno actual.",
    "Kết quả mô phỏng: {0}": "Resultado de la simulación: {0}",
    "Lượt nghe đang chờ xác nhận.": "La escucha está esperando confirmación.",
    "Lượt trước chưa hoàn tất. Bấm tiếp tục để dùng lại lượt đó, không tạo thanh toán trùng.": "Pase anterior no completado. Haga clic en continuar para reutilizar ese turno, sin crear pagos duplicados.",
    "Lắng nghe thiên nhiên. Kết nối di sản. Mở cửa 7:00 – 18:30 hàng ngày.": "Escuche la naturaleza. Conexión patrimonial. Abierto de 7:00 a 18:30 todos los días.",
