    "Lộ trình": "Hoja de ruta",
    "Lộ trình của bạn": "Su hoja de ruta",
    "Lộ trình demo do nhóm đề xuất. Đường nối chỉ thể hiện thứ tự điểm ghé, không phải chỉ đường đi bộ.": "Hoja de ruta de demostración propuesta por el equipo. Las líneas de conexión solo muestran el orden de las paradas, no las indicaciones para caminar.",
    "Lộ trình gợi ý": "Ruta sugerida",
    "Mang theo tai nghe và bắt đầu với ba bước đơn giản. Bạn luôn có thể dừng, nghe lại và khám phá theo cách của mình.": "Traiga sus auriculares y comience con tres sencillos pasos. Siempre puedes detenerte, escuchar de nuevo y explorar a tu manera.",
    "Mua vé trực tuyến hoặc đổi mã tiền mặt": "Compre boletos en línea o canjee códigos de efectivo",
    "Muôn điều để lắng nghe.": "Muchas cosas para escuchar.",
    "Mã hỗ trợ:": "Código de soporte:",
    "Mã không đúng, đã hết hạn hoặc đã được dùng. Bạn hãy kiểm tra lại với nhân viên.": "El código es incorrecto, ha caducado o ha sido utilizado. Por favor consulte con el personal.",
