    "Mã quầy hết hạn hoặc đã sử dụng? Nhờ nhân viên đối soát giao dịch. Xóa dữ liệu trình duyệt không cấp lại vé.": "¿El código de contador expiró o se usó? Solicite al personal que verifique las transacciones. Eliminar los datos del navegador no vuelve a emitir boletos.",
    "Mình có thể giúp gì cho bạn?": "¿Cómo puedo ayudarte?",
