    "Nguồn ảnh": "Fuente de imagen",
    "Ngôn ngữ giao diện": "Idioma de la interfaz",
    "Ngước nhìn những tán cây, tìm một khoảng râm mát và dành thời gian cho thế giới thực vật quanh mình. Mỗi bước đi là một góc nhìn mới.": "Mire los árboles, encuentre un lugar con sombra y pase tiempo con el mundo vegetal que le rodea. Cada paso es una nueva perspectiva.",
    "Ngọc lan": "Ngoc Lan",
    "Nhiều câu chuyện.": "Muchas historias.",
    "Nhập 6 chữ số nhân viên đã cấp sau khi nhận thanh toán.": "Ingrese el número de empleado de 6 dígitos emitido después de recibir el pago.",
    "Nhập mã tại quầy": "Ingresar código en el mostrador",
    "Nhập điều bạn muốn hỏi…": "Ingrese lo que desea preguntar…",
    "Những chú chim trĩ lông trắng đen, mặt đỏ tại Thảo Cầm Viên.": "Faisanes con plumas blancas y negras y caras rojas al Thảo Cầm Viên.",
    "Những khoảng xanh": "Espacios verdes",
    "Những người bạn nhỏ": "Pequeños amigos",
    "Những tán cây xanh vươn lên nền trời trong khuôn viên.": "Los árboles verdes llegan hasta el cielo en el campus.",
    "Nếu đã thanh toán mà chưa nghe được, hãy nhờ nhân viên kiểm tra trước khi thanh toán lại. Dùng cùng trình duyệt và giữ dữ liệu của trang để tiếp tục dùng vé.": "Si ha pagado pero no ha recibido respuesta, pídale a un miembro del personal que lo verifique antes de volver a pagar. Utilice el mismo navegador y conserve los datos del sitio para seguir usando los tickets.",
    "Nội dung đang được cập nhật theo ngôn ngữ bạn chọn.": "El contenido se está actualizando en el idioma que usted seleccionó.",
    "Phiên khách tham quan đã hết hạn hoặc không hợp lệ (mã 401).": "La sesión del visitante ha caducado o no es válida (código 401).",
    "Phiên đã được máy chủ xác minh. Bạn có thể bắt đầu tham quan.": "La sesión ha sido verificada por el servidor. Puedes empezar a hacer turismo.",
    "Phát lại từ đầu": "Repetir desde el principio",
    "Phân loại điểm": "Clasificación de puntos",
    "Phóng to": "Ampliar",
    "Phản hồi mô phỏng": "Respuesta de simulación",
    "Qua cánh cổng, chạm một miền ký ức.": "A través de la puerta, tocando un recuerdo.",
    "Quan sát sắc lông, dáng đi và những chuyển động nhỏ. Giữ khoảng cách, dành sự yên tĩnh cho các loài vật và để sự tò mò dẫn lối.": "Observe el color del pelaje, la forma de andar y los pequeños movimientos. Mantén la distancia, deja a los animales en paz y deja que tu curiosidad te guíe.",
    "Quyền nghe thuyết minh": "Derecho a escuchar explicaciones",
    "Quyền nghe đã hết hạn. Nếu vé của bạn vẫn còn hạn nhưng không mở được, hãy nhờ nhân viên kiểm tra.": "El permiso de escucha ha caducado. Si su boleto aún es válido pero no se puede abrir, pídale a un miembro del personal que lo verifique.",
    "Quyền nghe đến": "Derecho a oír",
    "Quán Nhan Hương": "Tienda Nhan Hương",
    "Rời nhịp phố, bước vào khoảng xanh. Lắng nghe câu chuyện của những tán cây và muôn loài, theo nhịp bước của riêng bạn.": "Salir de la ciudad, entrar en el espacio verde. Escuche las historias de los árboles y sus especies, a su propio ritmo.",
