    "Thanh toán chưa thành công. Kiểm tra lại hoặc nhờ nhân viên hỗ trợ trước khi tạo lượt khác.": "El pago no ha sido exitoso. Verifique nuevamente o solicite ayuda a un miembro del personal antes de realizar otro intento.",
    "Thanh toán chưa được xác nhận. Vui lòng chờ rồi kiểm tra lại.": "El pago no ha sido confirmado. Espere y verifique nuevamente.",
