    "Vé này đã được kích hoạt. Nếu không mở được quyền nghe, hãy nhờ nhân viên hỗ trợ; không cần trả tiền lại.": "Este ticket ha sido activado. Si no puede abrir los derechos de escucha, consulte al personal de soporte; no es necesario devolver el dinero.",
