    "Vé đã hết hạn hoặc quyền tham quan không còn hợp lệ. Nếu mất token, vui lòng liên hệ nhân viên; không thanh toán lại chỉ để khôi phục token.": "El billete ha caducado o la admisión ya no es válida. Si pierde su token, comuníquese con el personal; No vuelvas a pagar sólo para restaurar los tokens.",
