    "Để bảo vệ vé, hệ thống chưa gửi quyền truy cập sang địa chỉ hiện tại. Hãy mở lại trang đã dùng hoặc nhờ nhân viên kiểm tra.": "Para proteger el ticket, el sistema no ha enviado permiso de acceso a la dirección actual. Vuelva a abrir la página utilizada o pídale a un miembro del personal que la revise.",
