    "Chọn điểm yêu thích và lắng nghe câu chuyện bằng ngôn ngữ của bạn. Không cần tạo tài khoản.": "Choisissez votre endroit préféré et écoutez l'histoire dans votre propre langue. Pas besoin de créer un compte.",
