    "Có. Sau khi kích hoạt, vào Khám phá, chọn điểm tham quan rồi chủ động phát hoặc tạm dừng thuyết minh. Âm thanh không tự phát khi mở trang.": "Oui. Après l'activation, accédez à Explorer, sélectionnez une attraction, puis lancez activement ou mettez en pause la narration. Le son n'est pas joué automatiquement lors de l'ouverture de la page.",
