    "Ngước nhìn những tán cây, tìm một khoảng râm mát và dành thời gian cho thế giới thực vật quanh mình. Mỗi bước đi là một góc nhìn mới.": "Regardez les arbres, trouvez un endroit ombragé et passez du temps avec le monde végétal qui vous entoure. Chaque étape est une nouvelle perspective.",
    "Ngọc lan": "Ngoc Lan",
    "Nhiều câu chuyện.": "De nombreuses histoires.",
    "Nhập 6 chữ số nhân viên đã cấp sau khi nhận thanh toán.": "Saisissez le numéro d'employé à 6 chiffres émis après réception du paiement.",
    "Nhập mã tại quầy": "Saisir le code au guichet",
    "Nhập điều bạn muốn hỏi…": "Entrez ce que vous souhaitez demander…",
    "Những chú chim trĩ lông trắng đen, mặt đỏ tại Thảo Cầm Viên.": "Faisans à plumes noires et blanches et visages rouges au Thảo Cầm Viên.",
    "Những khoảng xanh": "Espaces verts",
    "Những người bạn nhỏ": "Petits amis",
    "Những tán cây xanh vươn lên nền trời trong khuôn viên.": "Les arbres verts s'élèvent jusqu'au ciel sur le campus.",
    "Nếu đã thanh toán mà chưa nghe được, hãy nhờ nhân viên kiểm tra trước khi thanh toán lại. Dùng cùng trình duyệt và giữ dữ liệu của trang để tiếp tục dùng vé.": "Si vous avez payé mais n'avez pas reçu de réponse, veuillez demander à un membre du personnel de vérifier avant de payer à nouveau. Utilisez le même navigateur et conservez les données du site pour continuer à utiliser les tickets.",
    "Nội dung đang được cập nhật theo ngôn ngữ bạn chọn.": "Le contenu est en cours de mise à jour dans la langue que vous avez sélectionnée.",
    "Phiên khách tham quan đã hết hạn hoặc không hợp lệ (mã 401).": "La session visiteur a expiré ou n'est pas valide (code 401).",
    "Phiên đã được máy chủ xác minh. Bạn có thể bắt đầu tham quan.": "La session a été vérifiée par le serveur. Vous pouvez commencer à visiter.",
    "Phát lại từ đầu": "Relecture depuis le début",
    "Phân loại điểm": "Classement par points",
    "Phóng to": "Agrandir",
    "Phản hồi mô phỏng": "Réponse de simulation",
    "Qua cánh cổng, chạm một miền ký ức.": "Par le portail, toucher un souvenir.",
    "Quan sát sắc lông, dáng đi và những chuyển động nhỏ. Giữ khoảng cách, dành sự yên tĩnh cho các loài vật và để sự tò mò dẫn lối.": "Observez la couleur du pelage, la démarche et les petits mouvements. Gardez vos distances, laissez les animaux tranquilles et laissez votre curiosité vous guider.",
    "Quyền nghe thuyết minh": "Droit d’écoute des explications",
    "Quyền nghe đã hết hạn. Nếu vé của bạn vẫn còn hạn nhưng không mở được, hãy nhờ nhân viên kiểm tra.": "L'autorisation d'écoute a expiré. Si votre billet est toujours valable mais ne peut pas être ouvert, veuillez demander à un membre du personnel de vérifier.",
    "Quyền nghe đến": "Droit d’entendre",
    "Quán Nhan Hương": "Boutique Nhan Hương",
    "Rời nhịp phố, bước vào khoảng xanh. Lắng nghe câu chuyện của những tán cây và muôn loài, theo nhịp bước của riêng bạn.": "Quittez la ville, entrez dans l'espace vert. Écoutez les histoires des arbres et de leurs espèces, à votre rythme.",
