    "Thanh toán chưa được xác nhận. Vui lòng chờ rồi kiểm tra lại.": "Le paiement n'a pas été confirmé. Veuillez patienter et vérifier à nouveau.",
    "Theo bóng mát, ngước nhìn những tán lá. Mỗi điểm dừng mở ra một góc nhìn khác về khu vườn.": "Suivez l'ombre, regardez le feuillage. Chaque arrêt ouvre une vue différente sur le jardin.",
