    "Tìm điểm tham quan trên bản đồ, chọn nơi bạn tò mò rồi mở thuyết minh. Từ muôn loài đến những tán cây, hành trình luôn theo nhịp của bạn.": "Recherchez les attractions sur la carte, choisissez le lieu qui vous intéresse, puis ouvrez la voix off. Des espèces aux arbres, le voyage se fait toujours à votre rythme.",
