    "Vé đã hết hạn hoặc quyền tham quan không còn hợp lệ. Nếu mất token, vui lòng liên hệ nhân viên; không thanh toán lại chỉ để khôi phục token.": "Le billet est expiré ou l'entrée n'est plus valable. Si vous perdez votre jeton, veuillez contacter le personnel ; Ne payez plus juste pour restaurer des jetons.",
