    "Vị trí tham khảo và minh họa, chưa khảo sát thực địa; không xác nhận lối vào hay khả năng tiếp cận. Đường nối các điểm không phải tuyến đi bộ.": "Localisation de référence et illustrative, pas d'enquête sur le terrain ; ne confirme pas l’entrée ou l’accessibilité. Les points de connexion des routes ne sont pas des itinéraires pédestres.",
