    "Động vật": "Animaux",
    "điểm": "points",
    "điểm tham quan": "sites touristiques",
    "điểm ·": "point ·",
    "đóng góp bản đồ": "carte contribuée",
    "ước tính từ thiết bị": "estimé à partir du dispositif",
    "Ảnh minh họa loài": "Illustration d'espèce",
    "Ảnh tư liệu địa điểm": "Photo documentaire de localisation",
    "Ảnh:": "Photo :",
    "Ở bản demo, nút bên dưới giả lập kết quả từ cổng thanh toán. Không có giao dịch tiền thật.": "Dans la démo, le bouton ci-dessous simule les résultats de la passerelle de paiement. Pas de trading en argent réel.",
    "— âm thanh chưa sẵn sàng": "— le son n'est pas prêt",
    "← Trở lại bản đồ": "← Retour à la carte",
