    "Cùng khám phá với {0} khách có vé còn hiệu lực": "Explorez avec {0} invités avec des billets valides",
    "Lộ trình demo do nhóm đề xuất — Hươu cao cổ và Voi châu Á": "Itinéraire de démonstration proposé par l'équipe — Girafe et éléphant d'Asie",
    "Tổng khoảng cách đường nối giữa các điểm: khoảng {0} m, không phải đường đi bộ.": "Distance routière totale entre les points : environ {0} m, pas un sentier pédestre.",
    "Tổng khoảng cách đường nối ước tính: {0} m. Không dùng để xác nhận đường đi hoặc khả năng tiếp cận.": "Distance totale estimée de la rampe : {0} m. Non utilisé pour confirmer l'itinéraire ou l'accessibilité.",
    "Vị trí mô phỏng theo sơ đồ cho demo; không xác nhận vị trí thực tế của cá thể hoặc cây.": "Localisation simulée selon schéma pour démonstration ; ne confirme pas l’emplacement réel de l’individu ou de l’arbre.",
    "Vị trí tham khảo OSM theo bản ghi nguồn đã lưu; chưa tái xác minh, chưa khảo sát thực địa.": "Emplacement de référence OSM selon l'enregistrement source enregistré ; Pas encore revérifié, pas encore d'enquête sur le terrain."
