    "Cổng sắt xanh mang tên Thảo Cầm Viên Sài Gòn dưới những tán cây.": "Cancello in ferro verde denominato Thảo Cầm Viên Sài Gòn sotto gli alberi.",
    "DEMO · KHÔNG THU TIỀN THẬT": "DEMO · NESSUN DENARO REALE RACCOLTO",
    "Danh sách điểm tham quan": "Elenco delle attrazioni",
    "Di tích": "Monumenti",
    "Dùng các điểm của lộ trình đang chọn": "Utilizza punti del percorso attualmente selezionato",
    "Dùng vị trí của tôi": "Usa la mia posizione",
    "Dùng vị trí thiết bị nếu được phép": "Utilizzare la posizione del dispositivo se consentito",
    "Dưới những tán cây xanh": "Sotto gli alberi verdi",
    "Dưới tán cây, tìm một chút bình yên.": "Sotto gli alberi trova un po' di pace.",
    "Dấu ấn di sản": "Marchio del patrimonio",
    "Dừng chân bên những chú chim trĩ. Quan sát sắc lông, lắng nghe âm thanh và khám phá câu chuyện của muôn loài.": "Fermatevi ai fagiani. Osserva i colori delle piume, ascolta i suoni e scopri le storie di tutte le specie.",
    "Dừng một chút. Khám phá nhiều hơn.": "Fermati un attimo. Esplora di più.",
    "Giới thiệu cho điểm này đang được cập nhật.": "L'introduzione a questo punto è in fase di aggiornamento.",
