    "Giữ cả số 0 ở đầu. Mã chỉ sử dụng một lần và có thời hạn.": "Mantenere anche gli zeri iniziali. Il codice può essere utilizzato solo una volta e ha un limite di tempo limitato.",
    "GẶP GỠ KHU VƯỜN": "INCONTRA IL GIARDINO",
    "Gặp một câu chuyện.": "Incontrare una storia.",
