    "Hình thức kích hoạt": "Modulo di attivazione",
    "Hôm nay, điều gì khiến bạn tò mò?": "Cosa ti incuriosisce oggi?",
    "Hươu cao cổ": "Giraffa",
    "Hỏi đáp khu vườn": "Domande e risposte sul giardino",
    "Hỏi đáp tạm thời gián đoạn. Câu hỏi vẫn được giữ để bạn thử lại; bản đồ và thuyết minh vẫn sử dụng được.": "Domande e risposte temporaneamente interrotte. La domanda rimane aperta affinché tu possa riprovare; Mappe e spiegazioni sono ancora disponibili.",
