    "Kích hoạt vé thuyết minh": "Attiva ticket voiceover",
    "Kích hoạt vé và bắt đầu nghe": "Attiva il ticket e inizia ad ascoltare",
    "Kích hoạt vé để hỏi thêm về động vật, cây xanh và các điểm tham quan.": "Attiva il ticket per chiedere maggiori informazioni su animali, alberi e attrazioni.",
    "Kích hoạt vé để xem và tùy chỉnh lộ trình.": "Attiva i biglietti per visualizzare e personalizzare i percorsi.",
    "Kết nối bị gián đoạn khi kích hoạt. Nhờ nhân viên kiểm tra kết quả trước khi nhập lại; không cần trả tiền lại.": "Connessione interrotta durante l'attivazione. Chiedere al personale di controllare i risultati prima di rientrare; non c'è bisogno di rimborsare.",
    "Kết nối bị gián đoạn. Bạn có thể thử lại để tiếp tục lượt đang có.": "Connessione interrotta. Puoi riprovare a continuare il tuo turno attuale.",
    "Kết quả mô phỏng: {0}": "Risultato della simulazione: {0}",
    "Lượt nghe đang chờ xác nhận.": "Ascolta è in attesa di conferma.",
    "Lượt trước chưa hoàn tất. Bấm tiếp tục để dùng lại lượt đó, không tạo thanh toán trùng.": "Passaggio precedente non completato. Fai clic su Continua per riutilizzare quel turno, senza creare pagamenti duplicati.",
    "Lắng nghe thiên nhiên. Kết nối di sản. Mở cửa 7:00 – 18:30 hàng ngày.": "Ascoltare la natura. Connessione al patrimonio. Aperto tutti i giorni dalle 7:00 alle 18:30.",
    "Lọc điểm tham quan": "Filtra i mirini",
    "Lộ trình": "Tabella di marcia",
    "Lộ trình của bạn": "La tua tabella di marcia",
    "Lộ trình demo do nhóm đề xuất. Đường nối chỉ thể hiện thứ tự điểm ghé, không phải chỉ đường đi bộ.": "Roadmap dimostrativa proposta dal team. Le linee di collegamento mostrano solo l'ordine delle fermate, non le indicazioni stradali.",
    "Lộ trình gợi ý": "Itinerario suggerito",
    "Mang theo tai nghe và bắt đầu với ba bước đơn giản. Bạn luôn có thể dừng, nghe lại và khám phá theo cách của mình.": "Porta con te le tue cuffie e inizia con tre semplici passaggi. Puoi sempre fermarti, riascoltare ed esplorare a modo tuo.",
    "Mua vé trực tuyến hoặc đổi mã tiền mặt": "Acquista i biglietti online o riscatta i codici contanti",
    "Muôn điều để lắng nghe.": "Molte cose da ascoltare.",
    "Mã hỗ trợ:": "Codice supporto:",
    "Mã không đúng, đã hết hạn hoặc đã được dùng. Bạn hãy kiểm tra lại với nhân viên.": "Il codice non è corretto, è scaduto o è stato utilizzato. Si prega di verificare con il personale.",
    "Mã kích hoạt 6 số": "Codice di attivazione a 6 cifre",
    "Mã kích hoạt gồm 6 chữ số": "Codice di attivazione a 6 cifre",
    "Mã quầy hết hạn hoặc đã sử dụng? Nhờ nhân viên đối soát giao dịch. Xóa dữ liệu trình duyệt không cấp lại vé.": "Codice contatore scaduto o utilizzato? Chiedi al personale di controllare le transazioni. L'eliminazione dei dati del browser non comporta la riemissione dei biglietti.",
    "Mình có thể giúp gì cho bạn?": "Come posso aiutarti?",
    "Mô phỏng thanh toán thành công (Demo)": "Simulare il pagamento andato a buon fine (Demo)",
