    "Một chiếc tai nghe.": "Una cuffia.",
    "Một cuộc gặp gỡ, nhiều điều kỳ diệu.": "Un incontro, tanti miracoli.",
    "Một khoảng trời, ngàn sắc lá.": "Un pezzo di cielo, mille colori di foglie.",
    "Một khoảng xanh giữa Sài Gòn": "Uno spazio verde tra Sài Gòn",
