    "Ngôn ngữ giao diện": "Lingua dell'interfaccia",
    "Ngước nhìn những tán cây, tìm một khoảng râm mát và dành thời gian cho thế giới thực vật quanh mình. Mỗi bước đi là một góc nhìn mới.": "Guarda gli alberi, trova un posto all'ombra e trascorri del tempo con il mondo vegetale che ti circonda. Ogni passo è una nuova prospettiva.",
    "Ngọc lan": "Ngoc Lan",
    "Nhiều câu chuyện.": "Molte storie.",
    "Nhập 6 chữ số nhân viên đã cấp sau khi nhận thanh toán.": "Inserire il numero del dipendente a 6 cifre rilasciato dopo aver ricevuto il pagamento.",
    "Nhập mã tại quầy": "Inserire il codice allo sportello",
    "Nhập điều bạn muốn hỏi…": "Inserisci ciò che vuoi chiedere...",
    "Những chú chim trĩ lông trắng đen, mặt đỏ tại Thảo Cầm Viên.": "Fagiani con piume bianche e nere e facce rosse al Thảo Cầm Viên.",
    "Những khoảng xanh": "Spazi verdi",
    "Những người bạn nhỏ": "Piccoli amici",
    "Những tán cây xanh vươn lên nền trời trong khuôn viên.": "Nel campus gli alberi verdi raggiungono il cielo.",
    "Nếu đã thanh toán mà chưa nghe được, hãy nhờ nhân viên kiểm tra trước khi thanh toán lại. Dùng cùng trình duyệt và giữ dữ liệu của trang để tiếp tục dùng vé.": "Se hai pagato ma non hai ricevuto risposta, chiedi a un membro del personale di verificare prima di pagare nuovamente. Utilizza lo stesso browser e conserva i dati del sito per continuare a utilizzare i ticket.",
    "Nội dung đang được cập nhật theo ngôn ngữ bạn chọn.": "Il contenuto viene aggiornato nella lingua selezionata.",
    "Phiên khách tham quan đã hết hạn hoặc không hợp lệ (mã 401).": "La sessione del visitatore è scaduta o non è valida (codice 401).",
    "Phiên đã được máy chủ xác minh. Bạn có thể bắt đầu tham quan.": "La sessione è stata verificata dal server. Puoi iniziare a visitare la città.",
