    "Phản hồi mô phỏng": "Risposta della simulazione",
    "Qua cánh cổng, chạm một miền ký ức.": "Attraverso il cancello, toccando un ricordo.",
    "Quan sát sắc lông, dáng đi và những chuyển động nhỏ. Giữ khoảng cách, dành sự yên tĩnh cho các loài vật và để sự tò mò dẫn lối.": "Osservare il colore del mantello, l'andatura e i piccoli movimenti. Mantieni le distanze, lascia stare gli animali e lascia che la tua curiosità ti apra la strada.",
    "Quyền nghe thuyết minh": "Diritto di ascoltare spiegazioni",
    "Quyền nghe đã hết hạn. Nếu vé của bạn vẫn còn hạn nhưng không mở được, hãy nhờ nhân viên kiểm tra.": "Il permesso di ascolto è scaduto. Se il tuo biglietto è ancora valido ma non può essere aperto, chiedi a un membro dello staff di controllarlo.",
    "Quyền nghe đến": "Diritto di sentire",
    "Quán Nhan Hương": "Negozio Nhan Hương",
    "Rời nhịp phố, bước vào khoảng xanh. Lắng nghe câu chuyện của những tán cây và muôn loài, theo nhịp bước của riêng bạn.": "Lasciare la città, entrare nello spazio verde. Ascolta le storie degli alberi e delle loro specie, al tuo ritmo.",
