    "Từ cánh cổng quen thuộc, bắt đầu hành trình tìm hiểu những câu chuyện gắn với Thảo Cầm Viên.": "Dal cancello familiare, inizia il viaggio per apprendere le storie associate a Thảo Cầm Viên.",
