    "VÉ THUYẾT MINH": "NOTE BIGLIETTI",
    "Vào": "Entra",
    "Vé của bạn đã sẵn sàng.": "Il tuo biglietto è pronto.",
    "Vé này đã được kích hoạt. Nếu chưa nhận được vé, hãy nhờ nhân viên hỗ trợ; không cần trả tiền lại.": "Questo ticket è stato attivato. Se non hai ricevuto il biglietto, chiedi assistenza al personale; non c'è bisogno di rimborsare.",
    "Vé này đã được kích hoạt. Nếu không mở được quyền nghe, hãy nhờ nhân viên hỗ trợ; không cần trả tiền lại.": "Questo ticket è stato attivato. Se non riesci ad aprire i diritti di ascolto, chiedi al personale di supporto; non c'è bisogno di rimborsare.",
    "Vé thuyết minh": "Biglietti audioguida",
    "Vé đang thuộc một địa chỉ khác": "Il biglietto si trova ad un indirizzo diverso",
    "Vé đã hết hạn hoặc quyền tham quan không còn hợp lệ. Nếu mất token, vui lòng liên hệ nhân viên; không thanh toán lại chỉ để khôi phục token.": "Il biglietto è scaduto oppure l'ingresso non è più valido. Se perdi il gettone rivolgiti allo staff; Non pagare di nuovo solo per ripristinare i token.",
    "Vé đã kích hoạt": "Il ticket è stato attivato",
    "Vé đã sẵn sàng. Mời bạn chọn điểm tham quan và bắt đầu nghe.": "I biglietti sono pronti. Scegli la tua destinazione e inizia ad ascoltare.",
    "Vé đã được kích hoạt. Bạn có thể bắt đầu khám phá và nghe thuyết minh.": "Il ticket è stato attivato. Puoi iniziare a esplorare e ascoltare la narrazione.",
    "Vé đã được lưu trên thiết bị.": "Il biglietto è stato salvato sul dispositivo.",
