    "Vị trí tham khảo và minh họa, chưa khảo sát thực địa; không xác nhận lối vào hay khả năng tiếp cận. Đường nối các điểm không phải tuyến đi bộ.": "Ubicazione di riferimento e illustrativa, nessuna indagine sul campo; non conferma l'ingresso o l'accessibilità. I punti di collegamento stradale non sono percorsi pedonali.",
