    "Chữ số {0}": "숫자 {0}",
    "Cuộc trò chuyện": "대화",
    "Các điểm muốn ghé": "방문하고 싶은 장소",
    "Cát anh": "깟안",
    "Câu hỏi của bạn": "귀하의 질문",
    "Có. Sau khi kích hoạt, vào Khám phá, chọn điểm tham quan rồi chủ động phát hoặc tạm dừng thuyết minh. Âm thanh không tự phát khi mở trang.": "가지다. 활성화 후 탐색으로 이동하여 명소를 선택한 다음 내레이션을 적극적으로 재생하거나 일시 중지하세요. 페이지를 열 때 소리가 자동으로 재생되지 않습니다.",
    "Cùng khám phá với": "함께 탐구해보자",
    "Cảnh báo bộ nhớ tạm: {0}. Dữ liệu có thể không giữ được khi tải lại trang.": "캐시 경고: {0}. 페이지를 다시 로드할 때 데이터가 유지되지 않을 수 있습니다.",
    "Cần kiểm tra với máy chủ trước khi mở quyền nghe. Bạn không cần nhập mã hoặc thanh toán lại.": "청취 권한을 열기 전에 서버에 확인이 필요합니다. 코드를 입력하거나 다시 결제할 필요가 없습니다.",
    "Cần trợ giúp với vé?": "티켓 관련 도움이 필요하신가요?",
