    "Dừng chân bên những chú chim trĩ. Quan sát sắc lông, lắng nghe âm thanh và khám phá câu chuyện của muôn loài.": "꿩들에게 들러라. 깃털의 색깔을 관찰하고, 소리를 듣고, 모든 종의 이야기를 알아보세요.",
    "Dừng một chút. Khám phá nhiều hơn.": "잠시만 멈춰주세요. 더 자세히 살펴보세요.",
