    "Chưa tạo được lộ trình.": "De route is niet gemaakt.",
    "Chưa tải được bản đồ. Bạn vẫn có thể chọn điểm trong danh sách để xem giới thiệu và nghe thuyết minh.": "Kaart kon niet worden geladen. U kunt nog steeds punten uit de lijst selecteren om introducties te zien en naar uitleg te luisteren.",
    "Chưa tải được giá.": "Kan prijs niet laden.",
    "Chưa tải được một phần nền bản đồ. Bạn vẫn có thể chọn điểm trong danh sách; thử tải lại trang khi kết nối ổn định.": "Een deel van de kaartachtergrond is niet geladen. U kunt nog steeds punten uit de lijst selecteren; Probeer de pagina opnieuw te laden wanneer de verbinding stabiel is.",
    "Chưa tải được nội dung. Kiểm tra kết nối rồi": "Inhoud kon niet worden geladen. Controleer dan de verbinding",
    "Chưa tải được ảnh. Bạn vẫn có thể đọc giới thiệu và nghe thuyết minh.": "Afbeelding kan niet worden geladen. Je kunt nog steeds de inleiding lezen en naar het verhaal luisteren.",
    "Chưa xác minh được quyền nghe. Bản đồ vẫn mở; thử lại sau hoặc liên hệ nhân viên.": "Luistertoestemming is niet geverifieerd. De kaart blijft open; Probeer het later opnieuw of neem contact op met het personeel.",
    "Chưa xác nhận được kết quả kích hoạt. Hãy nhờ nhân viên kiểm tra trước khi thử lại; không cần trả tiền lại.": "De activeringsresultaten zijn niet bevestigd. Vraag een medewerker om dit te controleren voordat u het opnieuw probeert; hoeft niet terug te betalen.",
    "Chưa xác nhận được quyền nghe của vé. Vui lòng nhờ nhân viên kiểm tra trước khi thanh toán lại.": "De luisterrechten van het ticket zijn niet bevestigd. Vraag een medewerker om dit te controleren voordat u opnieuw betaalt.",
    "Chạm nút phát để cho phép trình duyệt phát âm thanh.": "Tik op de afspeelknop zodat de browser audio kan afspelen.",
    "Chạm vào ký ức của Sài Gòn.": "De herinneringen van Sài Gòn aanraken.",
    "Chậm một bước.": "Eén stap langzaam.",
    "Chỉ còn một bước để mở câu chuyện đầu tiên.": "Er is nog maar één stap over om het eerste verhaal te openen.",
    "Chọn chủ đề khám phá": "Selecteer een verkenningsonderwerp",
    "Chọn các điểm muốn ghé. Thứ tự được gợi ý theo điểm gần tiếp theo, không phải tuyến đi bộ hay đường ngắn nhất.": "Selecteer de plaatsen die u wilt bezoeken. De volgorde wordt voorgesteld door het volgende dichtstbijzijnde punt, niet door de looproute of de kortste route.",
