    "Kết nối bị gián đoạn khi kích hoạt. Nhờ nhân viên kiểm tra kết quả trước khi nhập lại; không cần trả tiền lại.": "Verbinding onderbroken tijdens activering. Vraag het personeel om de resultaten te controleren voordat ze opnieuw binnenkomen; hoeft niet terug te betalen.",
    "Kết nối bị gián đoạn. Bạn có thể thử lại để tiếp tục lượt đang có.": "Verbinding onderbroken. Je kunt opnieuw proberen je huidige beurt voort te zetten.",
    "Kết quả mô phỏng: {0}": "Simulatieresultaat: {0}",
    "Lượt nghe đang chờ xác nhận.": "Luister wacht op bevestiging.",
    "Lượt trước chưa hoàn tất. Bấm tiếp tục để dùng lại lượt đó, không tạo thanh toán trùng.": "Vorige passage niet voltooid. Klik op Doorgaan om die beurt opnieuw te gebruiken, zonder dubbele betalingen te creëren.",
    "Lắng nghe thiên nhiên. Kết nối di sản. Mở cửa 7:00 – 18:30 hàng ngày.": "Luister naar de natuur. Erfgoedverbinding. Dagelijks geopend van 7.00 – 18.30 uur.",
    "Lọc điểm tham quan": "Filter bezienswaardigheden",
    "Lộ trình": "Routekaart",
    "Lộ trình của bạn": "Jouw routekaart",
    "Lộ trình demo do nhóm đề xuất. Đường nối chỉ thể hiện thứ tự điểm ghé, không phải chỉ đường đi bộ.": "Demo-roadmap voorgesteld door het team. Verbindingslijnen tonen alleen de volgorde van de haltes, geen looprichtingen.",
    "Lộ trình gợi ý": "Voorgestelde route",
    "Mang theo tai nghe và bắt đầu với ba bước đơn giản. Bạn luôn có thể dừng, nghe lại và khám phá theo cách của mình.": "Neem je koptelefoon mee en ga aan de slag met drie eenvoudige stappen. Je kunt altijd stoppen, opnieuw luisteren en op je eigen manier ontdekken.",
    "Mua vé trực tuyến hoặc đổi mã tiền mặt": "Koop online kaartjes of wissel geldcodes in",
    "Muôn điều để lắng nghe.": "Veel dingen om naar te luisteren.",
    "Mã hỗ trợ:": "Ondersteuningscode:",
    "Mã không đúng, đã hết hạn hoặc đã được dùng. Bạn hãy kiểm tra lại với nhân viên.": "De code is onjuist, verlopen of gebruikt. Neem contact op met het personeel.",
