    "Mã kích hoạt gồm 6 chữ số": "6-cijferige activeringscode",
    "Mã quầy hết hạn hoặc đã sử dụng? Nhờ nhân viên đối soát giao dịch. Xóa dữ liệu trình duyệt không cấp lại vé.": "Tellercode verlopen of gebruikt? Vraag het personeel om transacties te controleren. Het verwijderen van browsergegevens leidt niet tot het opnieuw uitgeven van tickets.",
    "Mình có thể giúp gì cho bạn?": "Hoe kan ik u helpen?",
