    "Nguồn ảnh": "Beeldbron",
    "Ngôn ngữ giao diện": "Interfacetaal",
    "Ngước nhìn những tán cây, tìm một khoảng râm mát và dành thời gian cho thế giới thực vật quanh mình. Mỗi bước đi là một góc nhìn mới.": "Kijk omhoog naar de bomen, zoek een schaduwplekje en breng tijd door met de plantenwereld om je heen. Elke stap is een nieuw perspectief.",
