    "Những tán cây xanh vươn lên nền trời trong khuôn viên.": "De groene bomen op de campus reiken tot aan de hemel.",
    "Nếu đã thanh toán mà chưa nghe được, hãy nhờ nhân viên kiểm tra trước khi thanh toán lại. Dùng cùng trình duyệt và giữ dữ liệu của trang để tiếp tục dùng vé.": "Als u betaald heeft maar nog niets heeft gehoord, vraag dan een medewerker om dit te controleren voordat u opnieuw betaalt. Gebruik dezelfde browser en bewaar de sitegegevens om tickets te kunnen blijven gebruiken.",
    "Nội dung đang được cập nhật theo ngôn ngữ bạn chọn.": "De inhoud wordt bijgewerkt in de taal die u hebt geselecteerd.",
    "Phiên khách tham quan đã hết hạn hoặc không hợp lệ (mã 401).": "Bezoekerssessie is verlopen of ongeldig (code 401).",
    "Phiên đã được máy chủ xác minh. Bạn có thể bắt đầu tham quan.": "De sessie is geverifieerd door de server. U kunt beginnen met bezienswaardigheden bekijken.",
