    "Qua cánh cổng, chạm một miền ký ức.": "Door het hek een herinnering aanraken.",
    "Quan sát sắc lông, dáng đi và những chuyển động nhỏ. Giữ khoảng cách, dành sự yên tĩnh cho các loài vật và để sự tò mò dẫn lối.": "Observeer vachtkleur, gang en kleine bewegingen. Houd afstand, laat de dieren met rust en laat uw nieuwsgierigheid de weg wijzen.",
    "Quyền nghe thuyết minh": "Recht om naar uitleg te luisteren",
    "Quyền nghe đã hết hạn. Nếu vé của bạn vẫn còn hạn nhưng không mở được, hãy nhờ nhân viên kiểm tra.": "Luistertoestemming is verlopen. Indien uw ticket nog geldig is maar niet kan worden geopend, kunt u een medewerker vragen om dit te controleren.",
