    "Rời nhịp phố, bước vào khoảng xanh. Lắng nghe câu chuyện của những tán cây và muôn loài, theo nhịp bước của riêng bạn.": "Verlaat de stad, stap de groene ruimte in. Luister in je eigen tempo naar de verhalen van de bomen en hun soort.",
