    "Vé của bạn đã sẵn sàng.": "Je ticket is klaar.",
    "Vé này đã được kích hoạt. Nếu chưa nhận được vé, hãy nhờ nhân viên hỗ trợ; không cần trả tiền lại.": "Dit ticket is geactiveerd. Als u uw ticket niet heeft ontvangen, vraag dan het personeel om hulp; hoeft niet terug te betalen.",
    "Vé này đã được kích hoạt. Nếu không mở được quyền nghe, hãy nhờ nhân viên hỗ trợ; không cần trả tiền lại.": "Dit ticket is geactiveerd. Als u luisterrechten niet kunt openen, vraag dan het ondersteunend personeel; hoeft niet terug te betalen.",
