    "Vị trí tham khảo và minh họa, chưa khảo sát thực địa; không xác nhận lối vào hay khả năng tiếp cận. Đường nối các điểm không phải tuyến đi bộ.": "Referentie- en illustratielocatie, geen veldonderzoek; bevestigt geen toegang of toegankelijkheid. Wegenverbindingspunten zijn geen looproutes.",
