    "Dấu ấn di sản": "Znak dziedzictwa",
    "Dừng chân bên những chú chim trĩ. Quan sát sắc lông, lắng nghe âm thanh và khám phá câu chuyện của muôn loài.": "Zatrzymaj się przy bażantach. Obserwuj kolory piór, słuchaj dźwięków i odkrywaj historie wszystkich gatunków.",
    "Dừng một chút. Khám phá nhiều hơn.": "Zatrzymaj się na chwilę. Odkryj więcej.",
