    "Hỏi đáp tạm thời gián đoạn. Câu hỏi vẫn được giữ để bạn thử lại; bản đồ và thuyết minh vẫn sử dụng được.": "Pytania i odpowiedzi tymczasowo przerwane. Pytanie pozostaje otwarte, możesz spróbować ponownie; Mapy i wyjaśnienia są nadal dostępne.",
