    "Không thể kiểm tra trạng thái phiên lúc này. Vui lòng kiểm tra kết nối mạng.": "W tej chwili nie można sprawdzić statusu sesji. Sprawdź połączenie sieciowe.",
    "Không thể kết nối máy chủ để tải gói dữ liệu tham quan.": "Nie można połączyć się z serwerem w celu pobrania pakietu danych wycieczki.",
    "Không thể kết nối tới máy chủ khi đổi quyền truy cập.": "Nie można połączyć się z serwerem podczas zmiany praw dostępu.",
    "Không thể thực hiện mô phỏng thanh toán.": "Nie można przeprowadzić symulacji płatności.",
    "Không thể tải tệp âm thanh. Vui lòng kiểm tra kết nối mạng.": "Nie można załadować pliku audio. Sprawdź połączenie sieciowe.",
    "Không tìm thấy mã xác thực hoặc thông tin phiên để đổi quyền.": "Nie można znaleźć tokena uwierzytelniającego ani informacji o sesji, aby zmienić uprawnienia.",
