    "Kéo để di chuyển · Bấm để trò chuyện · Alt + phím mũi tên để di chuyển": "Przeciągnij, aby przenieść · Stuknij, aby porozmawiać · Alt + klawisze strzałek, aby przenieść",
    "Kích hoạt lượt tham quan": "Aktywacja wycieczki",
    "Kích hoạt vé": "Aktywacja biletu",
    "Kích hoạt vé thuyết minh": "Aktywuj bilety lektorskie",
    "Kích hoạt vé và bắt đầu nghe": "Aktywuj bilet i zacznij słuchać",
    "Kích hoạt vé để hỏi thêm về động vật, cây xanh và các điểm tham quan.": "Aktywuj bilet, aby zapytać więcej o zwierzętach, drzewach i atrakcjach.",
    "Kích hoạt vé để xem và tùy chỉnh lộ trình.": "Aktywuj bilety, aby przeglądać i dostosowywać trasy.",
    "Kết nối bị gián đoạn khi kích hoạt. Nhờ nhân viên kiểm tra kết quả trước khi nhập lại; không cần trả tiền lại.": "Połączenie zostało przerwane podczas aktywacji. Poproś personel o sprawdzenie wyników przed ponownym wejściem; nie ma potrzeby spłacać.",
    "Kết nối bị gián đoạn. Bạn có thể thử lại để tiếp tục lượt đang có.": "Połączenie zostało przerwane. Możesz spróbować ponownie, aby kontynuować swoją obecną turę.",
    "Kết quả mô phỏng: {0}": "Wynik symulacji: {0}",
    "Lượt nghe đang chờ xác nhận.": "Słuchanie oczekuje na potwierdzenie.",
    "Lượt trước chưa hoàn tất. Bấm tiếp tục để dùng lại lượt đó, không tạo thanh toán trùng.": "Poprzedni przebieg nie został ukończony. Kliknij Kontynuuj, aby ponownie wykorzystać tę turę, bez tworzenia duplikatów płatności.",
    "Lắng nghe thiên nhiên. Kết nối di sản. Mở cửa 7:00 – 18:30 hàng ngày.": "Słuchaj natury. Połączenie dziedzictwa. Otwarte codziennie 7:00 – 18:30.",
    "Lọc điểm tham quan": "Celowniki z filtrem",
    "Lộ trình": "Plan działania",
    "Lộ trình của bạn": "Twój plan działania",
    "Lộ trình demo do nhóm đề xuất. Đường nối chỉ thể hiện thứ tự điểm ghé, không phải chỉ đường đi bộ.": "Plan działania wersji demonstracyjnej zaproponowany przez zespół. Linie łączące pokazują jedynie kolejność przystanków, a nie wskazówki dotyczące pieszych.",
    "Lộ trình gợi ý": "Sugerowana trasa",
    "Mang theo tai nghe và bắt đầu với ba bước đơn giản. Bạn luôn có thể dừng, nghe lại và khám phá theo cách của mình.": "Zabierz ze sobą słuchawki i zacznij od trzech prostych kroków. Zawsze możesz się zatrzymać, posłuchać ponownie i odkrywać na swój własny sposób.",
    "Mua vé trực tuyến hoặc đổi mã tiền mặt": "Kupuj bilety online lub realizuj kody gotówkowe",
