    "Mã hỗ trợ:": "Kod pomocniczy:",
    "Mã không đúng, đã hết hạn hoặc đã được dùng. Bạn hãy kiểm tra lại với nhân viên.": "Kod jest nieprawidłowy, wygasł lub został wykorzystany. Proszę sprawdzić u personelu.",
    "Mã kích hoạt 6 số": "6-cyfrowy kod aktywacyjny",
    "Mã kích hoạt gồm 6 chữ số": "6-cyfrowy kod aktywacyjny",
    "Mã quầy hết hạn hoặc đã sử dụng? Nhờ nhân viên đối soát giao dịch. Xóa dữ liệu trình duyệt không cấp lại vé.": "Kod licznika wygasł lub został wykorzystany? Poproś personel o sprawdzenie transakcji. Usunięcie danych przeglądarki nie powoduje ponownego wystawienia biletów.",
    "Mình có thể giúp gì cho bạn?": "Jak mogę Ci pomóc?",
