    "Ngước nhìn những tán cây, tìm một khoảng râm mát và dành thời gian cho thế giới thực vật quanh mình. Mỗi bước đi là một góc nhìn mới.": "Spójrz na drzewa, znajdź zacienione miejsce i spędź czas z otaczającym cię światem roślin. Każdy krok to nowa perspektywa.",
