    "Những tán cây xanh vươn lên nền trời trong khuôn viên.": "Zielone drzewa na terenie kampusu sięgają nieba.",
    "Nếu đã thanh toán mà chưa nghe được, hãy nhờ nhân viên kiểm tra trước khi thanh toán lại. Dùng cùng trình duyệt và giữ dữ liệu của trang để tiếp tục dùng vé.": "Jeśli zapłaciłeś, ale nie otrzymałeś odpowiedzi, poproś pracownika o sprawdzenie przed ponowną płatnością. Aby móc dalej korzystać z biletów, użyj tej samej przeglądarki i zachowaj dane witryny.",
    "Nội dung đang được cập nhật theo ngôn ngữ bạn chọn.": "Treść jest aktualizowana w wybranym przez Ciebie języku.",
    "Phiên khách tham quan đã hết hạn hoặc không hợp lệ (mã 401).": "Sesja gościa wygasła lub jest nieprawidłowa (kod 401).",
    "Phiên đã được máy chủ xác minh. Bạn có thể bắt đầu tham quan.": "Sesja została zweryfikowana przez serwer. Można rozpocząć zwiedzanie.",
    "Phát lại từ đầu": "Odtwórz od początku",
    "Phân loại điểm": "Klasyfikacja punktowa",
    "Phóng to": "Powiększ",
    "Phản hồi mô phỏng": "Odpowiedź symulacji",
    "Qua cánh cổng, chạm một miền ký ức.": "Przez bramę, dotykając wspomnienia.",
    "Quan sát sắc lông, dáng đi và những chuyển động nhỏ. Giữ khoảng cách, dành sự yên tĩnh cho các loài vật và để sự tò mò dẫn lối.": "Obserwuj kolor sierści, chód i drobne ruchy. Zachowaj dystans, zostaw zwierzęta w spokoju i pozwól, aby prowadziła Cię ciekawość.",
    "Quyền nghe thuyết minh": "Prawo do wysłuchania wyjaśnień",
    "Quyền nghe đã hết hạn. Nếu vé của bạn vẫn còn hạn nhưng không mở được, hãy nhờ nhân viên kiểm tra.": "Pozwolenie na słuchanie wygasło. Jeśli Twój bilet jest nadal ważny, ale nie można go otworzyć, poproś pracownika o sprawdzenie.",
    "Quyền nghe đến": "Prawo do słuchania",
    "Quán Nhan Hương": "Sklep Nhan Hương",
    "Rời nhịp phố, bước vào khoảng xanh. Lắng nghe câu chuyện của những tán cây và muôn loài, theo nhịp bước của riêng bạn.": "Opuść miasto, wejdź na zieloną przestrzeń. Posłuchaj opowieści o drzewach i ich gatunkach we własnym tempie.",
