    "Thanh toán chưa thành công. Kiểm tra lại hoặc nhờ nhân viên hỗ trợ trước khi tạo lượt khác.": "Płatność nie powiodła się. Sprawdź ponownie lub poproś pracownika o pomoc przed podjęciem kolejnej próby.",
    "Thanh toán chưa được xác nhận. Vui lòng chờ rồi kiểm tra lại.": "Płatność nie została potwierdzona. Proszę poczekać i sprawdzić ponownie.",
    "Theo bóng mát, ngước nhìn những tán lá. Mỗi điểm dừng mở ra một góc nhìn khác về khu vườn.": "Podążaj za cieniem, spójrz na liście. Każdy przystanek otwiera inny widok na ogród.",
