    "Nếu đã thanh toán mà chưa nghe được, hãy nhờ nhân viên kiểm tra trước khi thanh toán lại. Dùng cùng trình duyệt và giữ dữ liệu của trang để tiếp tục dùng vé.": "Se você pagou, mas não recebeu resposta, peça a um membro da equipe para verificar antes de pagar novamente. Use o mesmo navegador e guarde os dados do site para continuar usando tickets.",
