    "Đường nối và khoảng cách ước tính; không phải đường đi bộ thực tế.": "Costuras e distâncias estimadas; Não é um caminho de caminhada real.",
    "Đến trang Khám phá": "Vá para a página Explorar",
    "Để bảo vệ vé, hệ thống chưa gửi quyền truy cập sang địa chỉ hiện tại. Hãy mở lại trang đã dùng hoặc nhờ nhân viên kiểm tra.": "Para proteger o ticket, o sistema não enviou permissão de acesso ao endereço atual. Por favor, reabra a página usada ou peça a um membro da equipe para verificar.",
    "Để câu chuyện dẫn đường.": "Deixe a história guiar o caminho.",
    "Địa điểm": "Localização",
    "Đọc lời thuyết minh": "Leia a narração",
    "Động vật": "Animais",
    "điểm": "pontos",
    "điểm tham quan": "pontos turísticos",
    "điểm ·": "ponto ·",
    "đóng góp bản đồ": "mapa contribuído",
    "ước tính từ thiết bị": "estimado a partir do dispositivo",
    "Ảnh minh họa loài": "Ilustração da espécie",
    "Ảnh tư liệu địa điểm": "Foto documental de localização",
    "Ảnh:": "Foto:",
    "Ở bản demo, nút bên dưới giả lập kết quả từ cổng thanh toán. Không có giao dịch tiền thật.": "Na demonstração, o botão abaixo simula resultados do gateway de pagamento. Nenhuma negociação com dinheiro real.",
    "— âm thanh chưa sẵn sàng": "— som não pronto",
    "← Trở lại bản đồ": "← Voltar ao mapa",
    "👤 Vị trí hiện tại của bạn": "👤 Sua localização atual",
    "Cùng khám phá với {0} khách có vé còn hiệu lực": "Explore com {0} convidados com ingressos válidos",
    "Lộ trình demo do nhóm đề xuất — Hươu cao cổ và Voi châu Á": "Rota de demonstração proposta pela equipe — Girafa e Elefante Asiático",
    "Tổng khoảng cách đường nối giữa các điểm: khoảng {0} m, không phải đường đi bộ.": "Distância rodoviária total entre pontos: cerca de {0} m, não é um caminho para caminhada.",
    "Tổng khoảng cách đường nối ước tính: {0} m. Không dùng để xác nhận đường đi hoặc khả năng tiếp cận.": "Distância total estimada da rampa: {0} m. Não utilizado para confirmar rota ou acessibilidade.",
    "Vị trí mô phỏng theo sơ đồ cho demo; không xác nhận vị trí thực tế của cá thể hoặc cây.": "Localização simulada conforme diagrama para demonstração; não confirma a localização real do indivíduo ou árvore.",
    "Vị trí tham khảo OSM theo bản ghi nguồn đã lưu; chưa tái xác minh, chưa khảo sát thực địa.": "Localização de referência do OSM de acordo com registro de origem salvo; Ainda não verificado novamente, nenhuma pesquisa de campo ainda."
