    "Chọn một điểm trên bản đồ để khám phá.": "选择地图上的点来探索。",
    "Chọn một điểm, nghe một câu chuyện.": "选一个地点，听一个故事。",
    "Chọn ngôn ngữ bạn muốn nghe": "选择您想要收听的语言",
    "Chọn ngôn ngữ, chọn điểm đến": "选择语言，选择目的地",
    "Chọn thanh toán trực tuyến mô phỏng hoặc nhập mã sáu chữ số được nhân viên cấp tại quầy.": "选择模拟网上支付或输入柜台工作人员提供的六位代码。",
    "Chọn điểm dừng để xem giới thiệu": "选择站点查看介绍",
    "Chọn điểm ghé và điểm xuất phát hợp lệ.": "选择有效的目的地和出发点。",
    "Chọn điểm muốn ghé": "选择您想要游览的目的地",
    "Chọn điểm và bấm nghe để khám phá theo cách của bạn.": "选择一个点并单击“聆听”以您的方式探索它。",
    "Chọn điểm xuất phát; hiện chưa có vị trí của bạn.": "选择起始点；您的位置当前不可用。",
    "Chọn điểm yêu thích và lắng nghe câu chuyện bằng ngôn ngữ của bạn. Không cần tạo tài khoản.": "选择您最喜欢的地点并用您自己的语言聆听故事。无需创建帐户。",
    "Chữ số {0}": "数字 {0}",
    "Cuộc trò chuyện": "对话",
