    "Cát anh": "猫他",
    "Câu hỏi của bạn": "你的问题",
    "Có. Sau khi kích hoạt, vào Khám phá, chọn điểm tham quan rồi chủ động phát hoặc tạm dừng thuyết minh. Âm thanh không tự phát khi mở trang.": "是的。激活后，进入探索，选择一个景点，然后主动播放或暂停旁白。打开页面时不会自动播放声音。",
